"""Seating charts: students sorted by last name, in rows."""

from typing import Iterable, List

from rosterkit.models import Student


def _row_line(number: int, row: List[Student]) -> str:
    names = " | ".join(s.display_name for s in row)
    return f"Row {number}: {names}"


# ---
def seating_rows(
    students: Iterable[Student], seats_per_row: int
) -> List[str]:
    """One line of text per row, sorted by last name."""
    if seats_per_row <= 0:
        raise ValueError("seats_per_row must be positive")
    ordered = sorted(
        students, key=lambda s: (s.last_name, s.first_name)
    )
    if not ordered:
        raise ValueError("no students to seat")
    size = seats_per_row
    return [
        _row_line(i // size + 1, ordered[i : i + size])
        for i in range(0, len(ordered), size)
    ]

